(function(){
  'use strict';
  const el=id=>document.getElementById(id),esc=escapeHtml;
  let owner=accountUserId||'guest',prepared=null,current=null,busy=false,preparing=false,nonce=0,abort=null,history=[];
  function db(){return new Promise((resolve,reject)=>{const req=indexedDB.open('lc-document-study',1);req.onupgradeneeded=()=>req.result.createObjectStore('results',{keyPath:'key'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
  async function storage(action,value){const handle=await db();try{return await new Promise((resolve,reject)=>{const tx=handle.transaction('results',action==='list'?'readonly':'readwrite'),store=tx.objectStore('results');let request;if(action==='list')request=store.getAll();else if(action==='save')request=store.put(value);else request=store.delete(value);tx.oncomplete=()=>resolve(request.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}finally{handle.close()}}
  async function refreshHistory(){const requestedOwner=owner;try{const rows=await storage('list');if(owner!==requestedOwner)return;history=rows.filter(x=>x.owner===owner).sort((a,b)=>b.updated_at.localeCompare(a.updated_at));renderHistory()}catch{el('documentHistory').textContent='本机存储不可用，请导出结果。'}}
  function renderHistory(){el('documentHistory').innerHTML=history.length?history.map(x=>`<div class="document-history-row"><button class="text-btn" data-document-open="${esc(x.id)}">${esc(x.name)}<small>${x.results.length} / ${x.total} 段 · ${x.status==='complete'?'已完成':'部分完成'} · ${esc(new Date(x.updated_at).toLocaleDateString())}</small></button><button class="text-btn danger" aria-label="删除 ${esc(x.name)} 本机记录" data-document-delete="${esc(x.id)}">删除</button></div>`).join(''):'<p class="sub">完成翻译后，结果会保存在这里。</p>';el('documentHistory').querySelectorAll('[data-document-open]').forEach(b=>b.onclick=()=>{if(busy||preparing)return toast('请先停止处理。');++nonce;prepared=null;current=structuredClone(history.find(x=>x.id===b.dataset.documentOpen));el('documentLanguage').value=current.language;document.querySelector('[name=documentMode][value='+current.mode+']').checked=true;el('documentConsent').checked=false;el('documentFile').value='';el('documentInfo').textContent='已打开本机记录。部分记录若要继续处理，请重新选择原文件。';render();syncControls()});el('documentHistory').querySelectorAll('[data-document-delete]').forEach(b=>b.onclick=async()=>{if(busy||preparing)return toast('请先停止处理。');if(!confirm('删除这份资料的本机翻译与分析？原文件不受影响。'))return;const record=history.find(x=>x.id===b.dataset.documentDelete),requestedOwner=owner;await storage('delete',record.key);if(requestedOwner!==owner)return;if(current?.id===record.id)reset();await refreshHistory()})}
  async function persist(){if(!current||current.owner!==owner)return;const record=structuredClone(current);record.updated_at=new Date().toISOString();try{await storage('save',record);if(record.owner===owner)await refreshHistory()}catch{toast('本机保存失败，请立即导出译文。')}}
  function syncControls(){el('documentStart').disabled=busy||preparing||!prepared||!cloudAuthed||!el('documentConsent').checked||current?.status==='complete';el('documentStart').textContent=current?.status==='complete'?'翻译与分析已完成':busy?'正在翻译与分析…':preparing?'正在读取文件…':current?.results.length?'继续翻译与分析':'翻译并整理要点';el('documentCancel').classList.toggle('hidden',!busy);el('documentNew').disabled=busy||preparing;el('documentFile').disabled=busy||preparing;el('documentLanguage').disabled=busy||preparing||!!current?.results.length;document.querySelectorAll('[name=documentMode]').forEach(x=>x.disabled=busy||preparing||!!current?.results.length);el('documentAuthHint').textContent=cloudAuthed?'已登录 · Gemini 分段翻译，完成后汇总全篇要点。':'需要登录课伴；使用网站已配置的 Gemini 服务。';el('documentExport').disabled=!current?.results.length;el('documentProgress').classList.toggle('hidden',!current);if(current){el('documentProgress').max=current.total+1;el('documentProgress').value=current.results.length+(current.summary?1:0)}}
  function reset(){++nonce;abort?.abort();busy=false;prepared=null;current=null;el('documentFile').value='';el('documentConsent').checked=false;el('documentInfo').textContent='原文件先在本机准备，点击开始后才发送给 Gemini。';render();syncControls()}
  async function choose(file){if(busy||preparing)return;reset();if(!file)return;preparing=true;const requestNonce=nonce,requestedOwner=owner;el('documentInfo').textContent='正在本机读取文件…';syncControls();try{const result=await DocumentStudy.prepareFile(file);if(requestNonce!==nonce||requestedOwner!==owner)return;prepared=result;current={id:crypto.randomUUID(),owner,key:'',name:result.name,total:result.chunks.length,type:result.type,notice:result.notice,language:el('documentLanguage').value,mode:document.querySelector('[name=documentMode]:checked').value,results:[],summary:null,status:'ready',updated_at:new Date().toISOString()};current.key=owner+':'+current.id;el('documentInfo').textContent=result.name+' · '+result.notice;render()}catch(e){if(requestNonce===nonce)el('documentInfo').textContent='读取失败：'+e.message}finally{if(requestNonce===nonce){preparing=false;syncControls()}}}
  async function invoke(body,signal){const {data:{session},error}=await supabaseClient.auth.getSession();if(error||!session||session.user.id!==owner)throw Error('登录已过期，请重新登录。');const config=window.LECTURE_COMPANION_CONFIG||{},url=config.supabaseUrl||localStorage.getItem('lc_sb_url'),key=config.publishableKey||localStorage.getItem('lc_sb_key');const timeout=AbortSignal.timeout(135000);const combined=AbortSignal.any([signal,timeout]);const response=await fetch(url+'/functions/v1/summarize',{method:'POST',headers:{apikey:key,Authorization:'Bearer '+session.access_token,'Content-Type':'application/json'},body:JSON.stringify({...body,consent:true}),signal:combined});let result;try{result=await response.json()}catch{throw Error('服务返回无效内容，请重试。')}if(!response.ok||result.error)throw Error(result.error||'AI 请求失败。');return result}
  async function run(){if(busy||!prepared||!cloudAuthed||!el('documentConsent').checked)return;busy=true;abort=new AbortController();const requestNonce=++nonce,requestedOwner=owner,source=prepared,record=current,signal=abort.signal;record.language=el('documentLanguage').value;record.mode=document.querySelector('[name=documentMode]:checked').value;record.status='processing';syncControls();try{
      for(let i=record.results.length;i<source.chunks.length;i++){
        if(requestNonce!==nonce||requestedOwner!==owner||signal.aborted)return;
        const chunk=source.chunks[i];el('documentStatus').textContent='正在翻译 '+chunk.label+' · '+(i+1)+' / '+source.chunks.length;
        const data=await invoke({operation:'translate_document',title:record.name,language:record.language,mode:record.mode,...chunk},signal);
        if(requestNonce!==nonce||requestedOwner!==owner||signal.aborted)return;
        const result=DocumentStudy.validateTranslation(data.result);record.results.push({...result,label:chunk.label});record.model=data.model;render();syncControls();await persist();
      }
      if(requestNonce!==nonce||requestedOwner!==owner||signal.aborted)return;
      el('documentStatus').textContent='翻译已完成，正在汇总全篇学习要点…';
      const data=await invoke({operation:'analyze_document',title:record.name,language:record.language,mode:record.mode,digests:record.results.map(x=>({label:x.label,digest:x.digest+(x.warnings.length?'\n不可辨认或不确定：'+x.warnings.join('；').slice(0,300):'')}))},signal);
      if(requestNonce!==nonce||requestedOwner!==owner||signal.aborted)return;
      record.summary=data.summary;record.skills=data.skills;record.skill_version=data.skill_version;record.status='complete';render();showTab('summary');await persist();toast('资料翻译与学习分析已完成。');
    }catch(e){if(requestNonce!==nonce||requestedOwner!==owner)return;record.status='partial';el('documentStatus').textContent='处理未完成：'+(e.name==='AbortError'?'已停止；已完成段落可导出。':e.name==='TimeoutError'?'请求超时，请继续处理。':e.message)+' 已保留 '+record.results.length+' / '+record.total+' 段。';await persist();}
    finally{if(requestNonce===nonce){busy=false;syncControls()}}
  }
  function render(){const r=current;el('documentTitle').textContent=r?.name||'你的学习资料';if(!r){el('documentStatus').textContent='选择文件后，在这里查看译文和学习要点。';el('documentTranslation').innerHTML=emptyHtml;el('documentSummary').innerHTML='';el('documentReview').innerHTML='';showTab('translation');return}el('documentStatus').textContent=r.status==='complete'?'完整翻译与分析已完成 · '+r.total+' 段':r.results.length?'已翻译 '+r.results.length+' / '+r.total+' 段；全篇分析尚未完成。':'文件已准备 · '+r.total+' 段';el('documentTranslation').innerHTML=r.results.length?(!r.summary?'<p class="document-progress-note">这是已完成的部分译文。全篇处理完成后显示汇总要点；你可以随时导出当前结果。</p>':'')+r.results.map(x=>`<article class="document-section"><h3>${esc(x.label)}</h3><div class="document-bilingual"><p class="document-text">${esc(x.original||'本页无可辨认的正文。')}</p><p class="document-text">${esc(x.translation)}</p></div>${x.warnings.map(w=>'<p class="document-warning">'+esc(w)+'</p>').join('')}</article>`).join(''):'<div class="document-empty"><h3>资料已经准备好</h3><p>'+esc(r.notice)+'<br>确认语言与阅读方式，勾选同意后开始。</p></div>';const s=r.summary;if(!s){el('documentSummary').innerHTML='<p class="sub">翻译全部段落后，Gemini 会结合所选的分析方式整理全篇要点。</p>';el('documentReview').innerHTML='<p class="sub">完成分析后，可以在这里练习主动回忆。</p>';return}const list=(heading,values)=>'<h3>'+heading+'</h3><ul>'+values.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>';el('documentSummary').innerHTML='<p class="sub">'+(r.mode==='paper'?'文献证据分析':'课程学习整理')+' · Gemini '+esc(r.model||'')+'</p><h3>内容概要</h3><p>'+esc(s.overview)+'</p>'+list('核心要点',s.key_points)+'<h3>核心术语</h3><dl>'+s.key_terms.map(x=>'<dt>'+esc(x.term)+'</dt><dd>'+esc(x.explanation)+'</dd>').join('')+'</dl>'+list(r.mode==='paper'?'研究方法与证据判断':'知识结构与复习建议',s.analysis)+list('需要对照原文确认',s.unclear_points);el('documentReview').innerHTML='<p class="sub">先合上译文，用自己的话回答，再返回原文核查。作答不发送给 AI，也不自动评分。</p>'+s.review_questions.map((q,i)=>'<div class="document-review-answer"><label for="documentAnswer'+i+'">'+(i+1)+'. '+esc(q)+'</label><textarea id="documentAnswer'+i+'" data-document-answer="'+i+'" maxlength="5000" placeholder="写下你的理解，再对照原文…"></textarea></div>').join('');el('documentReview').querySelectorAll('textarea').forEach(t=>{t.value=r.answers?.[t.dataset.documentAnswer]||'';t.onchange=()=>{r.answers||={};r.answers[t.dataset.documentAnswer]=t.value;persist()}})}
  function showTab(name){document.querySelectorAll('[data-document-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.documentTab===name)));for(const key of ['translation','summary','review'])el('document'+key[0].toUpperCase()+key.slice(1)).classList.toggle('hidden',key!==name)}
  const emptyHtml=el('documentTranslation').innerHTML;
  el('documentFile').onchange=()=>choose(el('documentFile').files[0]);el('documentNew').onclick=reset;el('documentConsent').onchange=syncControls;el('documentStart').onclick=run;
  el('documentCancel').onclick=async()=>{if(!busy)return;abort.abort();++nonce;busy=false;if(current){current.status='partial';await persist();}el('documentStatus').textContent='已停止 · 已完成 '+(current?.results.length||0)+' / '+(current?.total||0)+' 段。点击继续可从下一段处理。';syncControls()};
  document.querySelectorAll('[data-document-tab]').forEach(b=>b.onclick=()=>showTab(b.dataset.documentTab));
  el('documentExport').onclick=()=>{if(!current?.results.length)return;const format=el('documentExportFormat').value;if(['docx','pdf'].includes(format)){const requestedOwner=owner,id=current.id;el('documentExport').disabled=true;HandoutExport.download(HandoutExport.fromDocument(structuredClone(current)),format,()=>owner===requestedOwner&&current?.id===id).catch(e=>toast('导出失败：'+e.message)).finally(syncControls);return}const content=format==='json'?JSON.stringify({format:'lecture-document-study-v1',...current,key:undefined,owner:undefined},null,2):DocumentStudy.exportMarkdown(current);const blob=new Blob(['\ufeff'+content],{type:format==='json'?'application/json':'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=current.name.replace(/\.[^.]+$/,'').replace(/[<>:"/\\|?*\x00-\x1f]/g,'_')+'-学习资料.'+format;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
  const drop=el('documentDrop');drop.ondragover=e=>{e.preventDefault();if(!busy&&!preparing)drop.classList.add('dragging')};drop.ondragleave=()=>drop.classList.remove('dragging');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('dragging');if(e.dataTransfer.files.length!==1)return toast('请每次选择一份资料。');choose(e.dataTransfer.files[0])};
  const accountChanged=window.studioAccountChanged;window.studioAccountChanged=function(){accountChanged?.();const next=accountUserId||'guest';if(next!==owner){abort?.abort();++nonce;busy=false;preparing=false;owner=next;prepared=null;current=null;history=[];el('documentConsent').checked=false;el('documentFile').value='';el('documentInfo').textContent='账户已切换，请重新选择资料。';render();renderHistory();refreshHistory()}syncControls()};
  refreshHistory();syncControls();
})();
